typedef enum { NS_HTML, NS_SVG, NS_MATHML } Namespace;

typedef enum { TEXT_DATA, TEXT_RCDATA, TEXT_PLAINTEXT } TextMode;

static bool custom_is(const Tag *tag, const char *name) {
    size_t length = strlen(name);
    return tag->type == CUSTOM && tag->custom_tag_name.size == length &&
           memcmp(tag->custom_tag_name.contents, name, length) == 0;
}

// Namespace of an element created by a start tag whose parent gives its children `context`.
static Namespace element_namespace(Namespace context, const Tag *tag) {
    if (tag->type == SVG) return NS_SVG;
    if (context == NS_HTML && tag->type == MATH) return NS_MATHML;
    return context;
}

// Children of SVG/MathML integration points get HTML start-tag processing. annotation-xml is an
// HTML integration point only with an encoding attribute the scanner does not see, so it stays foreign.
static Namespace children_namespace(Namespace ns, const Tag *tag) {
    if (ns == NS_SVG && (tag->type == TITLE || custom_is(tag, "FOREIGNOBJECT") || custom_is(tag, "DESC"))) {
        return NS_HTML;
    }
    if (ns == NS_MATHML && (custom_is(tag, "MI") || custom_is(tag, "MO") || custom_is(tag, "MN") ||
                            custom_is(tag, "MS") || custom_is(tag, "MTEXT"))) {
        return NS_HTML;
    }
    return ns;
}

// Namespace of the current node and the namespace its child start tags get.
static void current_namespaces(Scanner *scanner, Namespace *node, Namespace *children) {
    Namespace n = NS_HTML, c = NS_HTML;
    for (unsigned i = 0; i < scanner->tags.size; i++) {
        n = element_namespace(c, &scanner->tags.contents[i]);
        c = children_namespace(n, &scanner->tags.contents[i]);
    }
    *node = n;
    *children = c;
}

static TextMode text_mode(Scanner *scanner, const char **end_name) {
    if (scanner->tags.size == 0) return TEXT_DATA;
    Namespace node, children;
    current_namespaces(scanner, &node, &children);
    if (node != NS_HTML) return TEXT_DATA;
    Tag *top = array_back(&scanner->tags);
    if (top->type == TITLE) {
        *end_name = "TITLE";
        return TEXT_RCDATA;
    }
    if (top->type == TEXTAREA) {
        *end_name = "TEXTAREA";
        return TEXT_RCDATA;
    }
    return custom_is(top, "PLAINTEXT") ? TEXT_PLAINTEXT : TEXT_DATA;
}

static bool is_tag_end_char(int32_t c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\f' || c == '\r' || c == '/' || c == '>';
}

static bool is_ascii_alpha(int32_t c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'); }

static bool is_ascii_digit(int32_t c) { return c >= '0' && c <= '9'; }

static bool is_ascii_hex(int32_t c) { return is_ascii_digit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'); }

// Consumes ASCII letters; true when they spell `name` (upper case) and a tag-name terminator follows.
static bool scan_name_eq(TSLexer *lexer, const char *name) {
    unsigned i = 0;
    bool eq = true;
    while (is_ascii_alpha(lexer->lookahead)) {
        if (eq && name[i] != 0 && towupper(lexer->lookahead) == (wint_t)name[i]) {
            i++;
        } else {
            eq = false;
        }
        advance(lexer);
    }
    return eq && name[i] == 0 && is_tag_end_char(lexer->lookahead);
}

