static bool is_legacy_reference(const char *name, unsigned length) {
    for (unsigned i = 0; i < sizeof(LEGACY_REFERENCES) / sizeof(LEGACY_REFERENCES[0]); i++) {
        if (strlen(LEGACY_REFERENCES[i]) == length && memcmp(LEGACY_REFERENCES[i], name, length) == 0) return true;
    }
    return false;
}

// Lookahead is '&'. True when a character reference starts here: numeric (&#digits / &#x hex, ';'
// optional), a name followed by ';', or the longest legacy name without ';'. With `mark`, the token
// end is marked after the reference. ponytail: any alphanumeric name with ';' counts as a reference;
// the full WHATWG table would make unknown names like "&foo;" text.
static bool scan_char_ref(TSLexer *lexer, bool mark) {
    advance(lexer);
    if (lexer->lookahead == '#') {
        advance(lexer);
        bool hex = lexer->lookahead == 'x' || lexer->lookahead == 'X';
        if (hex) advance(lexer);
        bool digits = false;
        while (hex ? is_ascii_hex(lexer->lookahead) : is_ascii_digit(lexer->lookahead)) {
            digits = true;
            advance(lexer);
        }
        if (!digits) return false;
        if (lexer->lookahead == ';') advance(lexer);
        if (mark) lexer->mark_end(lexer);
        return true;
    }
    if (!is_ascii_alpha(lexer->lookahead)) return false;
    char name[8];
    unsigned length = 0;
    bool found = false;
    while (is_ascii_alpha(lexer->lookahead) || is_ascii_digit(lexer->lookahead)) {
        if (length < sizeof(name)) name[length] = (char)lexer->lookahead;
        length++;
        advance(lexer);
        if (length <= sizeof(name) && is_legacy_reference(name, length)) {
            found = true;
            if (mark) lexer->mark_end(lexer);
        }
    }
    if (lexer->lookahead == ';') {
        advance(lexer);
        if (mark) lexer->mark_end(lexer);
        return true;
    }
    return found;
}

// Text up to the next tag (data), the element's own end tag (RCDATA) or EOF (plaintext); character
// references end it except in plaintext. Leading and trailing whitespace stay extras.
static bool scan_text(TSLexer *lexer, TextMode mode, const char *end_name, const bool *valid_symbols) {
    bool has_text = false;
    if (mode != TEXT_PLAINTEXT && lexer->lookahead == '&') {
        if (valid_symbols[ENTITY] && scan_char_ref(lexer, true)) {
            lexer->result_symbol = ENTITY;
            return true;
        }
        has_text = true;
        lexer->mark_end(lexer);
    }
    while (!lexer->eof(lexer)) {
        int32_t c = lexer->lookahead;
        if (c == '<' && mode == TEXT_DATA) break;
        if (c == '<' && mode == TEXT_RCDATA) {
            advance(lexer);
            if (lexer->lookahead == '/') {
                advance(lexer);
                if (scan_name_eq(lexer, end_name)) break;
            }
            has_text = true;
            lexer->mark_end(lexer);
            continue;
        }
        if (c == '&' && mode != TEXT_PLAINTEXT) {
            if (scan_char_ref(lexer, false)) break;
            has_text = true;
            lexer->mark_end(lexer);
            continue;
        }
        advance(lexer);
        if (!iswspace(c)) {
            has_text = true;
            lexer->mark_end(lexer);
        }
    }
    if (!has_text) return false;
    lexer->result_symbol = TEXT;
    return true;
}

// Lookahead is the first '[' after "<!": a CDATA section up to "]]>" (foreign content only).
static bool scan_cdata_section(TSLexer *lexer) {
    for (const char *c = "[CDATA["; *c; c++) {
        if (lexer->lookahead != *c) return false;
        advance(lexer);
    }
    unsigned brackets = 0;
    while (!lexer->eof(lexer)) {
        if (lexer->lookahead == ']') {
            brackets++;
        } else if (lexer->lookahead == '>' && brackets >= 2) {
            advance(lexer);
            lexer->mark_end(lexer);
            lexer->result_symbol = CDATA_SECTION;
            return true;
        } else {
            brackets = 0;
        }
        advance(lexer);
    }
    return false;
}

